import leetcode.medium.OnlineStockSpan;
import org.junit.Test;
import static org.junit.Assert.*;

public class OnlineStockSpanTest { 

    @Test
    public void nextSinglePriceTest() {
        OnlineStockSpan spanCalculator = new OnlineStockSpan();

        int span = spanCalculator.next(100);

        assertEquals(1, span);
    }

    @Test
    public void nextMultiplePricesTest() {
        OnlineStockSpan spanCalculator = new OnlineStockSpan();

        int span1 = spanCalculator.next(100);
        int span2 = spanCalculator.next(80);
        int span3 = spanCalculator.next(60);
        int span4 = spanCalculator.next(70);
        int span5 = spanCalculator.next(60);
        int span6 = spanCalculator.next(75);
        int span7 = spanCalculator.next(85);

        assertEquals(1, span1);
        assertEquals(1, span2);
        assertEquals(1, span3);
        assertEquals(2, span4);
        assertEquals(1, span5);
        assertEquals(4, span6);
        assertEquals(6, span7);
    }

    @Test
    public void calculateSpansSinglePriceTest() {
        OnlineStockSpan spanCalculator = new OnlineStockSpan();

        int[] prices = {100};
        int[] spans = spanCalculator.calculateSpans(prices);

        assertArrayEquals(new int[]{1}, spans);
    }

    @Test
    public void calculateSpansMultiplePricesTest() {
        OnlineStockSpan spanCalculator = new OnlineStockSpan();

        int[] prices = {100, 80, 60, 70, 60, 75, 85};
        int[] spans = spanCalculator.calculateSpans(prices);

        assertArrayEquals(new int[]{1, 1, 1, 2, 1, 4, 6}, spans);
    }

    @Test(expected = IllegalArgumentException.class)
    public void calculateSpansNullPricesTest() {
        OnlineStockSpan spanCalculator = new OnlineStockSpan();

        spanCalculator.calculateSpans(null);
    }

    @Test
    public void calculateSpansEmptyPricesTest() {
        OnlineStockSpan spanCalculator = new OnlineStockSpan();

        int[] spans = spanCalculator.calculateSpans(new int[0]);

        assertArrayEquals(new int[]{}, spans);
    }
}
